import unittest
from solution import word_frequency

class T(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(word_frequency("a b a"), {"a": 2, "b": 1})
    def test_case(self):
        self.assertEqual(word_frequency("Hi hi HI"), {"hi": 3})
    def test_empty(self):
        self.assertEqual(word_frequency(""), {})
    def test_whitespace(self):
        self.assertEqual(word_frequency("a  b\ta\nb"), {"a": 2, "b": 2})
    def test_single(self):
        self.assertEqual(word_frequency("solo"), {"solo": 1})
